#pragma once
#include <cstddef>
#include <vector>

class IntStack
{
public:
    void push(int value);
    bool pop();
    int top() const;
    bool empty() const;
    std::size_t size() const;

private:
    std::vector<int> m_items{};
};

solution.IntStack.cpp:
#include "IntStack.h"

void IntStack::push(int value)
{
    m_items.push_back(value);
}

bool IntStack::pop()
{
    if (m_items.empty())
    {
        return false;
    }
    m_items.pop_back();
    return true;
}

int IntStack::top() const
{
    return m_items.empty() ? 0 : m_items.back();
}

bool IntStack::empty() const { return m_items.empty(); }
std::size_t IntStack::size() const { return m_items.size(); }

unitTests:
#include "IntStack.h"

TEST("starts empty") { const IntStack s{}; CHECK(s.empty()); CHECK_EQ(s.size(), 0u); CHECK_EQ(s.top(), 0); }
TEST("push and top") { IntStack s{}; s.push(3); s.push(7); CHECK_EQ(s.top(), 7); CHECK_EQ(s.size(), 2u); CHECK(!s.empty()); }
TEST("pop gives things back in reverse order") { IntStack s{}; s.push(1); s.push(2); s.push(3); CHECK(s.pop()); CHECK_EQ(s.top(), 2); CHECK(s.pop()); CHECK_EQ(s.top(), 1); CHECK(s.pop()); CHECK(s.empty()); }
TEST("pop on an empty stack") { IntStack s{}; CHECK(!s.pop()); CHECK(s.empty()); }

